// Seerah book generated by scripts/convert-seerah.mjs. Server components only.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

const DIR = path.join(process.cwd(), "data/seerah");

const load = cache(async <T>(file: string): Promise<T> =>
  JSON.parse(await fs.readFile(path.join(DIR, file), "utf8")),
);

/** p paragraph · h heading · s subheading · b bullet · a ayah line · l labeled (`k: x`). */
export type SeerahBlock = { t: "p" | "h" | "s" | "b" | "a" | "l"; x: string; k?: string };
export type SeerahLessonMeta = { id: string; slug: string; title: string; minutes: number };
export type SeerahLesson = SeerahLessonMeta & { blocks: SeerahBlock[] };
export type SeerahChapter = {
  id: string;
  title: string;
  period: string;
  minutes: number;
  lessons: SeerahLessonMeta[];
};
export type SeerahPart = {
  id: string;
  title: string;
  subtitle: string;
  period: string;
  chapters: SeerahChapter[];
};
/** [lesson id, title, plain text]. */
export type SeerahSearchEntry = [string, string, string];

/** A lesson with its place in the book (reading order across chapters). */
export type SeerahLessonRef = SeerahLessonMeta & {
  chapterId: string;
  chapterTitle: string;
  chapterPeriod: string;
  partTitle: string;
  indexInChapter: number;
  chapterSize: number;
};

export const getSeerahIndex = () => load<SeerahPart[]>("index.json");
export const getSeerahChapterLessons = (id: string) => load<SeerahLesson[]>(`chapters/${id}.json`);
export const getSeerahSearchIndex = () => load<SeerahSearchEntry[]>("search.json");

export const getSeerahLessons = cache(async (): Promise<SeerahLessonRef[]> =>
  (await getSeerahIndex()).flatMap((part) =>
    part.chapters.flatMap((ch) =>
      ch.lessons.map((l, i) => ({
        ...l,
        chapterId: ch.id,
        chapterTitle: ch.title,
        chapterPeriod: ch.period,
        partTitle: part.title,
        indexInChapter: i,
        chapterSize: ch.lessons.length,
      })),
    ),
  ),
);

export async function getSeerahChapter(id: string) {
  for (const part of await getSeerahIndex()) {
    const chapter = part.chapters.find((c) => c.id === id);
    if (chapter) return { part, chapter };
  }
  return null;
}

